// src/search/SearchAlgorithm.js
// ========================================
class SearchAlgorithm {
    constructor(grid, start, goal) {
        this.grid = grid;
        this.start = start;
        this.goal = goal;

        this.frontier = [];
        this.visited = [];
        this.finalPath = [];
        this.finished = false;
        this.found = false;
        this.cameFrom = new Map();
    }

    step() {
        // TODO: sobrescrever para processar somente um nó da busca.
    }

    isFinished() {
        return this.finished;
    }

    getPath() {
        return this.finalPath;
    }

    reconstructPath() {
        if (!this.found) {
            this.finalPath = [];
            return this.finalPath;
        }

        const path = [];
        let current = this.goal;

        while (current) {
            path.push(current);

            if (current === this.start) {
                break;
            }

            current = this.cameFrom.get(current);
        }

        if (path[path.length - 1] !== this.start) {
            this.finalPath = [];
            return this.finalPath;
        }

        this.finalPath = path.reverse();
        return this.finalPath;
    }

    finish(found) {
        this.finished = true;
        this.found = found;
        this.finalPath = found ? this.reconstructPath() : [];
    }

    reset() {
        this.frontier = [];
        this.visited = [];
        this.finalPath = [];
        this.finished = false;
        this.found = false;
        this.cameFrom = new Map();
    }
}


// ========================================
// src/search/PriorityQueue.js
// ========================================
class PriorityQueue {
    constructor() {
        this.items = [];
    }

    enqueue(element, priority) {
        const existingItem = this.items.find((item) => item.element === element);

        if (existingItem) {
            if (priority >= existingItem.priority) {
                return;
            }

            existingItem.priority = priority;
        } else {
            this.items.push({ element, priority });
        }

        this.items.sort((itemA, itemB) => itemA.priority - itemB.priority);
    }

    dequeue() {
        const item = this.items.shift();

        if (item) {
            return item.element;
        } else {
            return null;
        }
    }

    peek() {
        if (this.items.length > 0) {
            return this.items[0].element;
        } else {
            return null;
        }
    }

    isEmpty() {
        return this.items.length === 0;
    }

    size() {
        return this.items.length;
    }

    clear() {
        this.items = [];
    }

    contains(element) {
        return this.items.some((item) => item.element === element);
    }

    toArray() {
        return this.items.map((item) => item.element);
    }
}


