// src/search/AStar.js
// ========================================
class AStar extends SearchAlgorithm {
    constructor(grid, start, goal) {
        super(grid, start, goal);
        this.priorityQueue = new PriorityQueue();
        this.costSoFar = new Map();
        this.closed = new Set();
        this.minimumStepCost = AStar.getMinimumStepCost();

        this.init();
    }

    init() {
        if (this.start) {
            this.costSoFar.set(this.start, 0);
            this.priorityQueue.enqueue(this.start, this.getPriority(this.start, 0));
            this.frontier = this.priorityQueue.toArray();
        }
    }

    heuristic(cell) {
        // Manhattan conta passos; cada passo custa pelo menos o terreno mais barato.
        // Multiplicar por esse custo mantém a heurística admissível e consistente,
        // mas na mesma escala dos custos, o que deixa a A* bem mais focada que a UCS.
        return Heuristics.manhattan(cell, this.goal) * this.minimumStepCost;
    }

    getPriority(cell, costToCell) {
        const estimate = this.heuristic(cell);

        // Em empates de f = g + h, prefere o nó mais perto do objetivo.
        // O desempate é menor que qualquer diferença de custo, então não muda a ordem por f.
        return costToCell + estimate + estimate * AStar.TIE_BREAK;
    }

    step() {
        if (this.finished) {
            return;
        }

        if (this.priorityQueue.isEmpty()) {
            this.finish(false);
            return;
        }

        const current = this.priorityQueue.dequeue();
        this.closed.add(current);
        this.visited.push(current);

        if (current === this.goal) {
            this.frontier = this.priorityQueue.toArray();
            this.finish(true);
            return;
        }

        const currentCost = this.costSoFar.get(current);
        const neighbors = this.grid.getNeighbors(current);

        for (const neighbor of neighbors) {
            // Com heurística consistente, um nó expandido já tem custo mínimo.
            if (this.closed.has(neighbor)) {
                continue;
            }

            const newCost = currentCost + neighbor.cost;

            if (!this.costSoFar.has(neighbor) || newCost < this.costSoFar.get(neighbor)) {
                this.costSoFar.set(neighbor, newCost);
                this.cameFrom.set(neighbor, current);
                this.priorityQueue.enqueue(neighbor, this.getPriority(neighbor, newCost));
            }
        }

        this.frontier = this.priorityQueue.toArray();
    }

    reset() {
        super.reset();
        this.priorityQueue.clear();
        this.costSoFar.clear();
        this.closed = new Set();
        this.init();
    }

    static getMinimumStepCost() {
        let minimum = Infinity;

        for (const type of Object.keys(Terrain.TYPES)) {
            if (Terrain.isWalkable(type)) {
                minimum = Math.min(minimum, Terrain.getCost(type));
            }
        }

        return minimum;
    }
}

AStar.TIE_BREAK = 1e-6;


// ========================================
// src/agent/Agent.js
// ========================================
class Agent {
    constructor(position) {
        this.position = position;
        this.path = [];
        this.currentPathIndex = 0;
        this.isMoving = false;
        // Fração (0 a 1) já percorrida entre a célula atual e a próxima do caminho.
        this.stepProgress = 0;
    }

    setPosition(cell) {
        this.position = cell;
        this.stepProgress = 0;
    }

    setPath(path) {
        this.path = path;
        this.currentPathIndex = 0;
        this.stepProgress = 0;
        this.isMoving = path.length > 1;

        if (path.length > 0) {
            this.position = path[0];
        }
    }

    clearPath() {
        this.path = [];
        this.currentPathIndex = 0;
        this.stepProgress = 0;
        this.isMoving = false;
    }

    getTerrainSpeedMultiplier() {
        if (!this.position) {
            return 0;
        }

        return Terrain.getSpeedMultiplier(this.position.terrainType);
    }

    getNextCell() {
        return this.path[this.currentPathIndex + 1] || null;
    }

    hasReachedEnd() {
        return this.path.length > 0 && this.currentPathIndex === this.path.length - 1;
    }

    update(deltaMs = Agent.getFrameDelta()) {
        if (!this.isMoving) {
            return;
        }

        let remainingSeconds = Math.min(deltaMs, Agent.MAX_FRAME_DELTA_MS) / 1000;

        while (remainingSeconds > 0 && this.isMoving) {
            const nextCell = this.getNextCell();

            // A velocidade vem do terreno em que o agente está entrando,
            // coerente com o custo de entrada usado pelas buscas.
            const multiplier = Terrain.getSpeedMultiplier(nextCell.terrainType);
            const cellsPerSecond = Agent.BASE_SPEED * multiplier;

            if (cellsPerSecond <= 0) {
                this.isMoving = false;
                return;
            }

            const secondsToNextCell = (1 - this.stepProgress) / cellsPerSecond;

            if (remainingSeconds < secondsToNextCell) {
                this.stepProgress += remainingSeconds * cellsPerSecond;
                return;
            }

            remainingSeconds -= secondsToNextCell;
            this.currentPathIndex += 1;
            this.position = nextCell;
            this.stepProgress = 0;

            if (this.hasReachedEnd()) {
                this.isMoving = false;
            }
        }
    }

    display(cellSize) {
        if (!this.position) {
            return;
        }

        let col = this.position.col;
        let row = this.position.row;
        const nextCell = this.isMoving ? this.getNextCell() : null;

        // Interpola entre as células para o movimento parecer contínuo.
        if (nextCell) {
            col += (nextCell.col - col) * this.stepProgress;
            row += (nextCell.row - row) * this.stepProgress;
        }

        const centerX = col * cellSize + cellSize / 2;
        const centerY = row * cellSize + cellSize / 2;

        noStroke();
        fill(220, 50, 50);
        circle(centerX, centerY, cellSize * 0.55);
    }

    static getFrameDelta() {
        // deltaTime é fornecido pelo p5.js; fora do navegador assume 60 FPS.
        return typeof deltaTime === "number" ? deltaTime : 1000 / 60;
    }
}

// Células por segundo em areia; lama e água reduzem pelo multiplicador do terreno.
Agent.BASE_SPEED = 5;
// Evita saltos de várias células quando a aba fica em segundo plano.
Agent.MAX_FRAME_DELTA_MS = 100;


