// src/entities/Food.js
// ========================================
class Food {
    constructor(position) {
        this.position = position;
    }

    setPosition(cell) {
        this.position = cell;
    }

    relocate(grid, agentCell) {
        const previousPosition = this.position;
        const maxDistance = (grid.cols - 1) + (grid.rows - 1);
        const minimumDistance = Math.ceil(maxDistance * 0.45);
        const reachableCells = [];
        const pendingCells = [];
        const seen = new Set();

        if (agentCell && agentCell.walkable) {
            pendingCells.push(agentCell);
            seen.add(agentCell);
        }

        // Uma única travessia encontra o componente alcançável do agente.
        while (pendingCells.length > 0) {
            const currentCell = pendingCells.pop();

            if (currentCell !== agentCell) {
                reachableCells.push(currentCell);
            }

            for (const neighbor of grid.getNeighbors(currentCell)) {
                if (neighbor.walkable && !seen.has(neighbor)) {
                    seen.add(neighbor);
                    pendingCells.push(neighbor);
                }
            }
        }

        const distanceFromAgent = (cell) => Math.abs(cell.col - agentCell.col)
            + Math.abs(cell.row - agentCell.row);
        let candidates = reachableCells.filter((cell) => distanceFromAgent(cell) >= minimumDistance);

        // Se a distância preferida for impossível, use as células mais distantes.
        if (candidates.length === 0) {
            let farthestDistance = 0;

            for (const cell of reachableCells) {
                farthestDistance = Math.max(farthestDistance, distanceFromAgent(cell));
            }

            candidates = reachableCells.filter((cell) => distanceFromAgent(cell) === farthestDistance);
        }

        if (previousPosition && candidates.length > 1) {
            candidates = candidates.filter((cell) => cell.col !== previousPosition.col
                || cell.row !== previousPosition.row);
        }

        // Uma grade sem outra célula alcançável não tem um objetivo válido.
        if (candidates.length === 0) {
            this.position = null;
            return null;
        }

        const selectedCell = candidates[Math.floor(Math.random() * candidates.length)];
        this.setPosition(selectedCell);
        return selectedCell;
    }

    display(cellSize) {
        if (!this.position) {
            return;
        }

        const centerX = this.position.col * cellSize + cellSize / 2;
        const centerY = this.position.row * cellSize + cellSize / 2;

        noStroke();
        fill(60, 170, 75);
        circle(centerX, centerY, cellSize * 0.4);
    }
}


// ========================================
// src/ui/UI.js
// ========================================
class UI {
    constructor() {
        this.availableAlgorithms = ["BFS", "DFS", "UCS", "GREEDY", "ASTAR"];
        this.selectedAlgorithm = "BFS";
        this.speed = 1;
        this.pendingActions = [];
        this.controls = null;
        this.lastStatusHtml = "";
    }

    initialize() {
        // Fora do navegador (testes em Node) não há funções de DOM do p5.js.
        if (typeof createDiv !== "function") {
            return;
        }

        const panel = createDiv();
        panel.addClass("panel");
        createElement("h1", "Busca Inteligente em Grid").parent(panel);

        this.controls = {
            algorithmSelect: this.createAlgorithmSelect(panel),
            speedSlider: null,
            speedLabel: null,
            status: null
        };

        this.createActionButtons(panel);
        this.createSpeedControl(panel);

        this.controls.status = createDiv();
        this.controls.status.addClass("status");
        this.controls.status.parent(panel);

        this.createLegend(panel);
    }

    createAlgorithmSelect(panel) {
        const group = this.createGroup(panel, "Algoritmo");
        const select = createSelect();

        for (const name of this.availableAlgorithms) {
            select.option(UI.ALGORITHM_LABELS[name], name);
        }

        select.selected(this.selectedAlgorithm);
        select.parent(group);
        return select;
    }

    createActionButtons(panel) {
        const group = createDiv();
        group.addClass("buttons");
        group.parent(panel);

        const buttons = [
            { label: "Iniciar busca", action: UI.ACTIONS.START, primary: true },
            { label: "Reiniciar", action: UI.ACTIONS.RESET },
            { label: "Novo mapa", action: UI.ACTIONS.NEW_MAP }
        ];

        for (const definition of buttons) {
            const button = createButton(definition.label);
            button.parent(group);
            button.mousePressed(() => this.requestAction(definition.action));

            if (definition.primary) {
                button.addClass("primary");
            }
        }
    }

    createSpeedControl(panel) {
        const group = this.createGroup(panel, "Velocidade");
        const row = createDiv();
        row.addClass("speed");
        row.parent(group);

        this.controls.speedSlider = createSlider(UI.MIN_SPEED, UI.MAX_SPEED, this.speed, UI.SPEED_STEP);
        this.controls.speedSlider.parent(row);

        this.controls.speedLabel = createSpan(this.formatSpeed(this.speed));
        this.controls.speedLabel.parent(row);
    }

    createLegend(panel) {
        const legend = createDiv();
        legend.addClass("legend");
        legend.parent(panel);

        let html = "<h2>Terrenos</h2><ul>";

        for (const properties of Object.values(Terrain.TYPES)) {
            const cost = properties.walkable ? `custo ${properties.cost}` : "intransponível";
            html += this.legendItem(properties.color, `${properties.label} (${cost})`);
        }

        const colors = SearchVisualizer.COLORS;
        html += "</ul><h2>Busca</h2><ul>";
        html += this.legendItem(colors.visited, "Visitados");
        html += this.legendItem(colors.frontier, "Fronteira");
        html += this.legendItem(colors.path, "Caminho final");
        html += this.legendItem(UI.AGENT_COLOR, "Agente");
        html += this.legendItem(UI.FOOD_COLOR, "Comida");
        html += "</ul>";

        legend.html(html);
    }

    createGroup(panel, title) {
        const group = createDiv();
        group.addClass("group");
        group.parent(panel);
        createSpan(title).addClass("group-title").parent(group);
        return group;
    }

    legendItem(color, label) {
        return `<li><span class="swatch" style="background: rgb(${color[0]}, ${color[1]}, ${color[2]})"></span>${label}</li>`;
    }

    setSelectedAlgorithm(name) {
        if (this.availableAlgorithms.includes(name)) {
            this.selectedAlgorithm = name;

            if (this.controls) {
                this.controls.algorithmSelect.selected(name);
            }

            return true;
        }

        return false;
    }

    getSelectedAlgorithm() {
        return this.selectedAlgorithm;
    }

    getSpeed() {
        return this.speed;
    }

    requestAction(action) {
        this.pendingActions.push(action);
    }

    consumeActions() {
        const actions = this.pendingActions;
        this.pendingActions = [];
        return actions;
    }

    update() {
        if (!this.controls) {
            return;
        }

        const selected = this.controls.algorithmSelect.value();

        if (this.availableAlgorithms.includes(selected)) {
            this.selectedAlgorithm = selected;
        }

        this.speed = Number(this.controls.speedSlider.value());
    }

    display(status) {
        if (!this.controls || !status) {
            return;
        }

        this.controls.speedLabel.html(this.formatSpeed(this.speed));

        // Só reescreve o painel quando algo muda, para não refazer o DOM a cada quadro.
        const html = this.buildStatusHtml(status);

        if (html !== this.lastStatusHtml) {
            this.controls.status.html(html);
            this.lastStatusHtml = html;
        }
    }

    buildStatusHtml(status) {
        let html = `<p class="state state-${status.state.toLowerCase()}">${UI.STATE_LABELS[status.state]}</p>`;

        if (status.message) {
            html += `<p class="message">${status.message}</p>`;
        }

        html += "<dl>";
        html += `<dt>Algoritmo</dt><dd>${UI.ALGORITHM_LABELS[status.algorithm]}</dd>`;
        html += `<dt>Nós visitados</dt><dd>${status.visited}</dd>`;
        html += `<dt>Fronteira</dt><dd>${status.frontier}</dd>`;
        html += `<dt>Passos do caminho</dt><dd>${status.pathSteps}</dd>`;
        html += `<dt>Custo do caminho</dt><dd>${status.pathCost}</dd>`;
        html += `<dt>Comidas coletadas</dt><dd>${status.score}</dd>`;
        html += "</dl>";

        return html + this.buildResultsHtml(status.results);
    }

    buildResultsHtml(results) {
        if (!results || results.size === 0) {
            return "";
        }

        let html = "<h2>Comparação neste mapa</h2><table><thead><tr>";
        html += "<th>Algoritmo</th><th>Visitados</th><th>Passos</th><th>Custo</th>";
        html += "</tr></thead><tbody>";

        for (const name of this.availableAlgorithms) {
            const result = results.get(name);

            if (!result) {
                continue;
            }

            const steps = result.found ? result.pathSteps : "—";
            const cost = result.found ? result.pathCost : "sem caminho";
            html += `<tr><td>${name === "ASTAR" ? "A*" : name}</td><td>${result.visited}</td>`;
            html += `<td>${steps}</td><td>${cost}</td></tr>`;
        }

        return html + "</tbody></table>";
    }

    formatSpeed(speed) {
        return `${speed}x`;
    }
}

UI.ACTIONS = Object.freeze({
    START: "START",
    RESET: "RESET",
    NEW_MAP: "NEW_MAP"
});

UI.ALGORITHM_LABELS = Object.freeze({
    BFS: "Busca em Largura (BFS)",
    DFS: "Busca em Profundidade (DFS)",
    UCS: "Custo Uniforme (UCS)",
    GREEDY: "Gulosa (Melhor Primeiro)",
    ASTAR: "A*"
});

UI.STATE_LABELS = Object.freeze({
    WAITING: "Aguardando",
    SEARCHING: "Buscando…",
    MOVING: "Agente a caminho da comida",
    COLLECTING: "Comida alcançada!"
});

UI.MIN_SPEED = 0.25;
UI.MAX_SPEED = 4;
UI.SPEED_STEP = 0.25;

// Mesmas cores usadas em Agent.display() e Food.display().
UI.AGENT_COLOR = Object.freeze([220, 50, 50]);
UI.FOOD_COLOR = Object.freeze([60, 170, 75]);


// ========================================
// src/ui/SearchVisualizer.js
// ========================================
class SearchVisualizer {
    constructor(cellSize) {
        this.cellSize = cellSize;

        // Estado apenas visual: não altera a busca nem o ciclo da simulação.
        this.trackedSearch = null;
        this.pathFrames = 0;
    }

    display(search) {
        if (!search) {
            return;
        }

        this.updatePathAnimation(search);

        this.drawVisited(search.visited);
        this.drawFrontier(search.frontier);
        this.drawCurrent(search);
        this.drawPath(search.finalPath);
    }

    updatePathAnimation(search) {
        // Reinicia a animação quando uma nova busca começa ou a atual é reiniciada.
        if (search !== this.trackedSearch || search.finalPath.length === 0) {
            this.trackedSearch = search;
            this.pathFrames = 0;
        } else {
            this.pathFrames += 1;
        }
    }

    drawVisited(visited) {
        const colors = SearchVisualizer.COLORS;
        const trailLength = SearchVisualizer.TRAIL_LENGTH;
        const trailStart = visited.length - trailLength;

        push();
        noStroke();

        for (let i = 0; i < visited.length; i += 1) {
            // Os nós visitados mais recentemente ficam mais intensos,
            // formando um rastro que mostra o avanço da busca passo a passo.
            const recency = i >= trailStart ? (i - trailStart + 1) / trailLength : 0;
            const visitedOpacity = colors.visitedAlpha + (colors.trailAlpha - colors.visitedAlpha) * recency;

            fill(...colors.visited, visitedOpacity);
            this.drawCell(visited[i], 1);
        }

        pop();
    }

    drawFrontier(frontier) {
        const colors = SearchVisualizer.COLORS;

        push();
        stroke(...colors.frontierStroke);
        strokeWeight(2);
        fill(...colors.frontier);

        for (const cell of frontier) {
            this.drawCell(cell, this.cellSize * 0.25);
        }

        pop();
    }

    drawCurrent(search) {
        // O último nó visitado é o que acabou de ser expandido.
        if (search.isFinished() || search.visited.length === 0) {
            return;
        }

        const current = search.visited[search.visited.length - 1];

        push();
        noFill();
        stroke(...SearchVisualizer.COLORS.current);
        strokeWeight(3);
        this.drawCell(current, 2);
        pop();
    }

    drawPath(path) {
        if (!path || path.length === 0) {
            return;
        }

        const colors = SearchVisualizer.COLORS;
        const visibleCells = this.getVisiblePathLength(path);

        push();
        noFill();

        // O contorno escuro deixa o caminho legível sobre qualquer terreno.
        stroke(...colors.pathOutline);
        strokeWeight(this.cellSize * 0.3);
        this.drawPathSegments(path, visibleCells);

        stroke(...colors.path);
        strokeWeight(this.cellSize * 0.16);
        this.drawPathSegments(path, visibleCells);

        pop();
    }

    drawPathSegments(path, visibleCells) {
        if (visibleCells === 1) {
            const center = this.getCenter(path[0]);
            point(center.x, center.y);
            return;
        }

        for (let i = 1; i < visibleCells; i += 1) {
            const from = this.getCenter(path[i - 1]);
            const to = this.getCenter(path[i]);
            line(from.x, from.y, to.x, to.y);
        }
    }

    getVisiblePathLength(path) {
        // O caminho é revelado do início ao objetivo, uma célula a cada poucos quadros.
        const revealed = 1 + Math.floor(this.pathFrames / SearchVisualizer.PATH_FRAMES_PER_CELL);
        return Math.min(path.length, revealed);
    }

    getCenter(cell) {
        return {
            x: cell.col * this.cellSize + this.cellSize / 2,
            y: cell.row * this.cellSize + this.cellSize / 2
        };
    }

    drawCell(cell, inset) {
        rect(
            cell.col * this.cellSize + inset,
            cell.row * this.cellSize + inset,
            this.cellSize - inset * 2,
            this.cellSize - inset * 2
        );
    }
}

SearchVisualizer.TRAIL_LENGTH = 12;
SearchVisualizer.PATH_FRAMES_PER_CELL = 2;

SearchVisualizer.COLORS = Object.freeze({
    visited: Object.freeze([95, 55, 135]),
    visitedAlpha: 120,
    trailAlpha: 220,
    frontier: Object.freeze([255, 130, 20, 225]),
    frontierStroke: Object.freeze([130, 60, 0]),
    current: Object.freeze([255, 255, 255]),
    path: Object.freeze([255, 225, 0]),
    pathOutline: Object.freeze([35, 35, 35, 225])
});


// ========================================
// src/core/SimulationState.js
// ========================================
const SimulationState = Object.freeze({
    WAITING: "WAITING",
    SEARCHING: "SEARCHING",
    MOVING: "MOVING",
    COLLECTING: "COLLECTING"
});


// ========================================
// src/core/Simulation.js
// ========================================
class Simulation {
    constructor(options = {}) {
        const cols = options.cols || 20;
        const rows = options.rows || 15;
        const cellSize = options.cellSize || 40;

        this.grid = new Grid(cols, rows, cellSize);
        this.initialAgentCell = this.grid.getRandomWalkableCell();
        this.agent = new Agent(this.initialAgentCell);
        this.food = new Food(null);
        this.food.relocate(this.grid, this.agent.position);
        this.ui = new UI();
        this.searchVisualizer = new SearchVisualizer(cellSize);
        this.search = null;
        this.searchAlgorithmName = null;
        this.stepBudget = 0;
        this.score = 0;
        this.message = "Gere um novo mapa ou inicie uma busca.";
        // Só compare resultados com o mesmo início e objetivo no mapa atual.
        this.results = new Map();
        this.resultsStart = null;
        this.resultsGoal = null;
        this.state = SimulationState.WAITING;

        this.ui.initialize();
    }

    generateNewMap() {
        this.grid.generateProcedural();

        const startCell = this.grid.getRandomWalkableCell();
        this.initialAgentCell = startCell;
        this.agent.setPosition(startCell);
        this.agent.clearPath();
        this.food.relocate(this.grid, startCell);
        this.search = null;
        this.searchAlgorithmName = null;
        this.stepBudget = 0;
        this.results.clear();
        this.resultsStart = null;
        this.resultsGoal = null;
        this.message = "Novo mapa gerado. Escolha um algoritmo e inicie a busca.";
        this.setState(SimulationState.WAITING);
    }

    resetSimulation() {
        this.generateNewMap();
    }

    update() {
        this.ui.update();
        this.handleUIActions();

        if (this.state === SimulationState.WAITING) {
            this.updateWaiting();
        } else if (this.state === SimulationState.SEARCHING) {
            this.updateSearching();
        } else if (this.state === SimulationState.MOVING) {
            this.updateMoving();
        } else if (this.state === SimulationState.COLLECTING) {
            this.updateCollecting();
        }
    }

    handleUIActions() {
        for (const action of this.ui.consumeActions()) {
            if (action === UI.ACTIONS.START) {
                this.startSearch();
            } else if (action === UI.ACTIONS.RESET) {
                this.resetSimulation();
            } else if (action === UI.ACTIONS.NEW_MAP) {
                this.generateNewMap();
            }
        }
    }

    updateWaiting() {
        // A simulação aguarda o usuário iniciar uma busca.
    }

    updateSearching() {
        if (!this.search) {
            return;
        }

        // A velocidade define quantos step() rodam por quadro; abaixo de 1x,
        // o orçamento acumula e a busca avança um nó a cada poucos quadros.
        this.stepBudget += this.ui.getSpeed();

        while (this.stepBudget >= 1 && !this.search.isFinished()) {
            this.search.step();
            this.stepBudget -= 1;
        }

        if (this.search.isFinished()) {
            this.handleSearchFinished();
        }
    }

    handleSearchFinished() {
        this.recordResult();

        if (!this.search.found) {
            this.message = "Nenhum caminho até a comida foi encontrado.";
            this.setState(SimulationState.WAITING);
            return;
        }

        this.agent.setPath(this.search.getPath());

        if (this.agent.isMoving) {
            this.message = "";
            this.setState(SimulationState.MOVING);
        } else {
            this.collectFood();
        }
    }

    updateMoving() {
        this.agent.update(Agent.getFrameDelta() * this.ui.getSpeed());

        if (!this.agent.isMoving) {
            this.collectFood();
        }
    }

    collectFood() {
        if (this.state === SimulationState.COLLECTING) {
            return;
        }

        if (!this.food.position || this.agent.position !== this.food.position) {
            this.message = "O agente parou antes de alcançar a comida.";
            this.setState(SimulationState.WAITING);
            return;
        }

        this.score += 1;
        this.message = "Comida coletada! A próxima busca começará da posição atual.";
        this.setState(SimulationState.COLLECTING);
    }

    updateCollecting() {
        this.food.relocate(this.grid, this.agent.position);
        this.results.clear();
        this.search = null;
        this.searchAlgorithmName = null;
        this.startSearch({ resetAgent: false });
    }

    startSearch(options = {}) {
        if (!this.food.position) {
            this.message = "Não há comida alcançável neste mapa.";
            this.setState(SimulationState.WAITING);
            return;
        }

        // O início manual preserva a comparação; a coleta continua da célula atual.
        if (options.resetAgent !== false) {
            this.agent.setPosition(this.initialAgentCell);
        }

        this.agent.clearPath();

        if (this.resultsStart !== this.agent.position || this.resultsGoal !== this.food.position) {
            this.results.clear();
        }

        this.resultsStart = this.agent.position;
        this.resultsGoal = this.food.position;
        const algorithmName = this.ui.getSelectedAlgorithm();

        this.search = this.createSearchAlgorithm(
            algorithmName,
            this.agent.position,
            this.food.position
        );
        this.searchAlgorithmName = algorithmName;
        this.stepBudget = 0;
        this.message = "";

        this.setState(SimulationState.SEARCHING);
    }

    createSearchAlgorithm(algorithmName, start, goal) {
        if (algorithmName === "BFS") {
            return new BFS(this.grid, start, goal);
        }

        if (algorithmName === "DFS") {
            return new DFS(this.grid, start, goal);
        }

        if (algorithmName === "UCS") {
            return new UniformCostSearch(this.grid, start, goal);
        }

        if (algorithmName === "GREEDY") {
            return new GreedySearch(this.grid, start, goal);
        }

        if (algorithmName === "ASTAR") {
            return new AStar(this.grid, start, goal);
        }

        throw new Error(`Algoritmo desconhecido: ${algorithmName}`);
    }

    recordResult() {
        const path = this.search.getPath();

        this.results.set(this.searchAlgorithmName, {
            found: this.search.found,
            visited: this.search.visited.length,
            pathSteps: Math.max(path.length - 1, 0),
            pathCost: this.getPathCost(path)
        });
    }

    getPathCost(path) {
        // O custo de um passo é o custo de entrar na célula; o início não é cobrado.
        let total = 0;

        for (let i = 1; i < path.length; i += 1) {
            total += path[i].cost;
        }

        return total;
    }

    getStatus() {
        const search = this.search;
        const path = search ? search.getPath() : [];

        return {
            state: this.state,
            algorithm: this.searchAlgorithmName || this.ui.getSelectedAlgorithm(),
            visited: search ? search.visited.length : 0,
            frontier: search ? search.frontier.length : 0,
            pathSteps: Math.max(path.length - 1, 0),
            pathCost: this.getPathCost(path),
            score: this.score,
            message: this.message,
            results: this.results
        };
    }

    display() {
        this.grid.display();
        this.searchVisualizer.display(this.search);
        this.food.display(this.grid.cellSize);
        this.agent.display(this.grid.cellSize);
        this.ui.display(this.getStatus());
    }

    setState(state) {
        if (!Object.values(SimulationState).includes(state)) {
            throw new Error(`Estado de simulação inválido: ${state}`);
        }

        this.state = state;
    }
}


// ========================================
// sketch.js
// ========================================
let simulation;

function setup() {
    createCanvas(800, 600);

    simulation = new Simulation({
        cols: 20,
        rows: 15,
        cellSize: 40
    });
    simulation.generateNewMap();
}

function draw() {
    background(245);

    simulation.update();
    simulation.display();
}

